"""Non-workflow top-level CLI verb registry (harness-lines burndown MF.1-r2).

Every new top-level CLI verb used to edit scripts/harness.py's argparse table in
main() -- a single-slot merge bottleneck. The NON-workflow top-level subcommand
groups (status .. graph-build-code-ast, plus the protected-files / executor /
agents groups) now register here. Adding a future verb is two steps and ZERO
harness.py edits:

    1. write its handler as cmd_<verb> in a harness_lib module (or harness.py);
    2. add one `p = sub.add_parser("<verb>"); ...; p.set_defaults(func=h.cmd_<verb>)`
       line to register() below.

DW.4's request router registers its verb here the same way.

register(sub, h): `sub` is the argparse _SubParsersAction; `h` is the harness
runtime module, passed by harness.py as sys.modules[__name__] so this module
never imports harness (no circular import). Handlers resolve as h.cmd_*.

Module-level values beyond the handler functions are imported here from their
real harness_lib home, never reached back out of harness.py:
  * records.LOG_KINDS (the `log` verb's kind choices) -> from harness_lib import records
argparse.REMAINDER (models/routing) is stdlib.

The workflow subcommand tree stays inline in harness.py: its `wsub.add_parser`
literals and the handoff/workflow-id/state boundary literals are pinned by
spec_test_gate.py. This module registers everything EXCEPT that tree.
"""
from __future__ import annotations

import argparse

from harness_lib import acceptances, adversarial_loop, anomaly_card, artifacts, audit_leg, capabilities_view, cli_catalog, commit_authority, config_keys, context_checkpoint, cost_metrics, decision_inbox, dep_graph, docs_tree, experiment_registry, failure_patterns, gate_perf, gate_staged, graph_providers, intake_queue, keys_vault, lane_schedule, mutation_probe, overseer_review, playbook_registry, records, repo_health, research_admin, scenario_isolation, scenario_run, services, spec_index, tasks_board, ui_proof, validation_stamp, vendor_fuel


def register(sub, h) -> None:
    """Register the non-workflow top-level subcommands on `sub`.

    Registration order is preserved byte-for-byte from the original main()
    table so `harness.py --help` output is unchanged.
    """
    p = sub.add_parser("commit", help="Execute a governed commit via CommitAuthority"); p.add_argument("-m", "--message", required=True); p.add_argument("--bypass-reason"); p.add_argument("--actor"); p.add_argument("--no-verify", action="store_true"); p.set_defaults(func=commit_authority.cmd_commit)
    p = sub.add_parser("governance-state", help="Inspect current vendor-neutral governance state"); p.add_argument("--commit", help="Query exact commit-proof tie transaction for SHA (PA-10)"); p.add_argument("--proof-graph", action="store_true", help="Generate verifiable proof graph (ER-14)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=adversarial_loop.cmd_governance_state)

    p = sub.add_parser("hold", help="Inspect and recover gate holds (PA-12)"); p.add_argument("action", nargs="?", choices=["list", "inspect", "recover", "abandon"], default="list"); p.add_argument("name", nargs="?"); p.add_argument("--json", action="store_true"); p.set_defaults(func=scenario_isolation.cmd_hold)


    p = sub.add_parser("status"); p.add_argument("--html", action="store_true", help="Write the read-only supervision snapshot page (SPEC-104)"); p.add_argument("--output", help="Where to write the page; default .harness/state/supervision.html"); p.set_defaults(func=h.cmd_status)
    p = sub.add_parser("escalations", help="List pending agent escalations; --resolve <id> marks one handled; --target <name|self> scopes the view AND guards resolve (no cross-subject resolve)"); p.add_argument("--resolve", metavar="ESCALATION_ID"); p.add_argument("--target", metavar="NAME_OR_SELF", help="Subject scope: a registered target name or 'self' (the harness)"); p.set_defaults(func=h.cmd_escalations)
    p = sub.add_parser("chat", help="Conversational harness-operator REPL: delegate harness control to an agent (engines: claude, codex, openai-compatible incl. local models)"); p.add_argument("--engine", choices=["claude", "codex", "openai", "manual"], help="Omit to pick interactively; manual = no agent, you type harness.py subcommands yourself"); p.add_argument("--model", help="Model for the engine (required for --engine openai)"); p.add_argument("--effort", help="Pass-through to claude --effort"); p.add_argument("--endpoint", help="OpenAI-compatible base URL (default: OPENAI_BASE_URL env)"); p.add_argument("--api-key-env", default="OPENAI_API_KEY", help="Env var holding the API key for --engine openai (optional for local servers)"); p.add_argument("--no-input", action="store_true", help="Never prompt; missing required values fail with exit 2 (SPEC-111)"); p.add_argument("--reconfigure", action="store_true", help="Re-run the setup wizard and local-setup checklist"); p.add_argument("--reset-prefs", action="store_true", help="Delete saved chat preferences (.harness/runtime/chat-prefs.json)"); p.add_argument("--target", help="Work on a registered target repository (SPEC-110/R25); omit to use saved prefs or the interactive picker"); p.add_argument("--role", default="router", help="Routing role whose model+prompt the chat front runs on (SPEC-144). Default router = the sonnet front-desk that dispatches demands; overseer restores the fable operator"); p.set_defaults(func=h.cmd_chat)
    p = sub.add_parser("ui", help="Browser supervision panel (SPEC-114): loopback HTTP + token; dashboard/escalations/records/chat tabs over allowlisted subcommands"); p.add_argument("--port", type=int, default=8787); p.add_argument("--engine", choices=["manual", "claude"], help="Chat-tab engine override; omit to use saved chat prefs"); p.add_argument("--no-open", action="store_true", help="Headless: do not auto-open a browser (agents MUST pass this; the bare verb is hook-denied from the Bash tool)"); p.add_argument("--exit-after-seconds", type=float, default=None, help="Stop serving after N seconds; spawned/test panels pass this so a hard-killed parent cannot orphan the server (omit = serve forever)"); p.set_defaults(func=h.cmd_ui)
    p = sub.add_parser("acceptances", help="Which vendor hooks are SKIPPED until the owner accepts them in the vendor's own UI (row env-acceptances-inbox)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=acceptances.cmd_acceptances, action=None)
    apsub = p.add_subparsers(dest="action")
    ap = apsub.add_parser("accept", help="Act on the pending acceptances: --mode visible (default) hands you the command to run; --mode headless drives the vendor's own TUI in a hidden pty, one separately-authorized key at a time, and falls back to visible on ANY refusal, missing pywinpty or unreachable screen reader"); ap.add_argument("--vendor", choices=["codex"], required=True); ap.add_argument("--mode", choices=["visible", "headless"], default="visible"); ap.add_argument("--dry-run", action="store_true", help="Report only; never launch or type")
    p = sub.add_parser("ui-proof", help="Run a Node proof driver against an in-process panel and detached Vite server"); p.add_argument("--driver", required=True, help="Playwright .mjs driver; MUST live under ui/ (e.g. ui/tests/x.tmp.mjs) — Node ESM resolves packages from the script's path, not cwd. Contract: argv[2]=baseUrl argv[3]=token"); p.add_argument("--panel-port", type=int, default=8787); p.add_argument("--timeout", type=int, default=180); p.set_defaults(func=ui_proof.cmd_ui_proof)
    p = sub.add_parser("discover", help="Route discovery cheaply: code -> local AST graph; text/images -> Gemini/NVIDIA free tiers; never the coder LLM"); p.add_argument("paths", nargs="*"); p.add_argument("--target", help="Operate on a registered target repository (SPEC-110)"); p.set_defaults(func=h.cmd_discover)
    p = sub.add_parser("doc-find", help="Where is X documented? Queries the cheap-API docs enrichment for file pointers instead of re-reading the docs tree"); p.add_argument("terms", nargs="*"); p.add_argument("--target", help="Query a registered target repository's enrichment (SPEC-110)"); p.set_defaults(func=h.cmd_doc_find)
    p = sub.add_parser("self-review", help="Self-evolution loop (SPEC-109): analyze harness metrics, raise improvement findings as escalations, apply safe actions"); p.set_defaults(func=h.cmd_self_review)
    p = sub.add_parser("metrics", help="Cost/token/time ledger summary (SPEC-111 R26): spend by model/target/day, expensive workflows, estimator calibration"); p.set_defaults(func=h.cmd_metrics)
    p = sub.add_parser("delegation", help="Record a subagent delegation in the cost ledger (R26/R27): planner->implementer/explore runs are real spend; --outcome feeds the per-lane yield rollup (metrics delegations.byOutcome)"); p.add_argument("model"); p.add_argument("--tokens", type=int, required=True); p.add_argument("--agent-type", required=True, help="the delegated lane's type (planner|implementer|explore|scanner|...); REQUIRED — a silent 'implementer' default mislabelled planner/scanner lanes in metrics delegations.byModel ('the audit'), so the seat must be named, never guessed (session-seat-unwired)"); p.add_argument("--tool-uses", type=int); p.add_argument("--duration-s", type=float); p.add_argument("--task"); p.add_argument("--target"); p.add_argument("--outcome", choices=["kept", "partial", "rejected", "reworked"], help="Overseer verdict on the delivered work (ort item 4)"); p.add_argument("--effort", help="The delegated seat's effort — with role+model it completes the seat metrics group by"); p.add_argument("--caller-seat", help="role:model:effort of the seat that DELEGATED (default: the session's HARNESS_SESSION_* triplet; never guessed from the routing pin)"); p.set_defaults(func=h.cmd_delegation)
    p = sub.add_parser("defect", help="Declare ONE defect against the seat(s) it belongs to (which seat PRODUCED it, which MISSED it), OR `defect ingest [PATH|-]` to record a reviewer's structured capsules (metrics defectsBySeat; info-only, never a score)"); p.add_argument("defect_class", choices=[*cost_metrics.DEFECT_CLASSES, "ingest"], help="a controlled class to DECLARE one defect, or `ingest` to record a reviewer HARNESS_RESULT's reviewFindings[].defect capsules"); p.add_argument("path", nargs="?", help="ingest only: a reviewer-result JSON file, or `-`/omitted for stdin"); p.add_argument("--producer", help="role:model:effort, or `self`; omit when genuinely unknown"); p.add_argument("--missed-by", help="role:model:effort, or `self` — the seat that accepted the work without catching it"); p.add_argument("--evidence", help="<commit|gate-run|audit|owner-report>:<ref> — (class, evidence) is the identity: re-declaring it CORRECTS attribution instead of adding a second defect, so give distinct findings in one artifact distinct refs (commit:4d5a90f#stale-pair)"); p.set_defaults(func=cost_metrics.cmd_defect)
    p = sub.add_parser("log", help="Record a worklog entry (SPEC-112 records ledger): kind + --title/--body/--ref/--tag, or --from-head to fill from the last commit"); p.add_argument("kind", choices=list(records.LOG_KINDS)); p.add_argument("--title"); p.add_argument("--body"); p.add_argument("--ref", action="append"); p.add_argument("--tag", action="append"); p.add_argument("--from-head", action="store_true", help="Fill missing title/body from the head commit and append its sha to refs"); p.add_argument("--supersedes", help="Title of an earlier record this one replaces (G3a): the target demotes early to the archive, drops from the head, but stays searchable below live"); p.set_defaults(func=h.cmd_log)
    p = sub.add_parser("records", help="Query the project ledger just-in-time (SPEC-112): search|recent|rebuild the derived index over worklog, escalations, validations, commits, specs"); p.add_argument("action", choices=["search", "recent", "rebuild", "sources", "summarize"]); p.add_argument("terms", nargs="*"); p.add_argument("--kind"); p.add_argument("--limit", type=int); p.set_defaults(func=h.cmd_records)
    p = sub.add_parser("targets", help="Governed target repositories (SPEC-110): list health, `targets add <name> <path>` to register a repo, or `targets sync <name>` to generate the adapter (env/MCP) on demand"); p.add_argument("action", nargs="?", choices=["list", "sync", "add"], default="list"); p.add_argument("name", nargs="?"); p.add_argument("path", nargs="?"); p.set_defaults(func=h.cmd_targets)
    p = sub.add_parser("models", help="Model-card CRUD (SPEC-115): list|catalog|show|add|set|remove|replace over .harness/routing/model-cards.json"); p.add_argument("rest", nargs=argparse.REMAINDER); p.set_defaults(func=h.cmd_models)
    p = sub.add_parser("routing", help="Role-based model routing (SPEC-115): show|set-role|profile|target|restore-canonical|replace; canonical is derived from task-profiles"); p.add_argument("rest", nargs=argparse.REMAINDER); p.set_defaults(func=h.cmd_routing)
    p = sub.add_parser("classify"); p.add_argument("words", nargs="*"); p.add_argument("--task"); p.set_defaults(func=h.cmd_classify)
    p = sub.add_parser("handoff"); p.add_argument("words", nargs="*"); p.add_argument("--task"); p.add_argument("--executor"); p.set_defaults(func=h.cmd_handoff)
    p = sub.add_parser("spawn-command"); p.add_argument("words", nargs="*"); p.add_argument("--task"); p.add_argument("--executor"); p.add_argument("--resume", help="build a codex `exec resume <SESSION_ID>` that re-pins the routed seat (D1.5); pass `last` for --last"); p.set_defaults(func=h.cmd_spawn)
    p = sub.add_parser("scenario", help="Run one testing/scenarios script, optionally detached with a completion marker"); p.add_argument("name"); p.add_argument("--detach", action="store_true"); p.add_argument("--run", action="store_true", help=argparse.SUPPRESS); p.add_argument("--marker", help=argparse.SUPPRESS); p.set_defaults(func=scenario_run.cmd_scenario)
    p = sub.add_parser("lane", help="Schedule a detached executor lane"); p.add_argument("action", choices=["schedule"]); p.add_argument("--at"); p.add_argument("--date"); p.add_argument("--executor", required=True); p.add_argument("--instruction-file", required=True); p.add_argument("--model"); p.add_argument("--effort"); p.add_argument("--probe", action="store_true"); p.add_argument("--run", action="store_true", help=argparse.SUPPRESS); p.add_argument("--marker", help=argparse.SUPPRESS); p.add_argument("--fire-at", help=argparse.SUPPRESS); p.set_defaults(func=lane_schedule.cmd_lane, spawn_command=h.spawn_command)
    p = sub.add_parser("validate-result"); p.add_argument("file"); p.set_defaults(func=h.cmd_validate)
    p = sub.add_parser("event"); p.add_argument("name"); p.add_argument("--payload"); p.set_defaults(func=h.cmd_event)
    p = sub.add_parser("graph-status"); p.set_defaults(func=h.cmd_graph_status)
    p = sub.add_parser("graph-build-code-ast", help="Generate graphify-out from Graphify code AST without network or external tools"); p.add_argument("--max-files", type=int); p.add_argument("--gemini-doc", action="append", help="opt-in: enrich this text doc via the Gemini free-tier fallback chain (requires llmAssisted.enabled and GEMINI_API_KEY/GOOGLE_API_KEY)"); p.add_argument("--target", help="Build the AST graph of a registered target repository (SPEC-110)"); p.set_defaults(func=h.cmd_graph_build_code_ast)

    pp = sub.add_parser("protected-files", help="Check canonical agent-file protection snapshots")
    psub = pp.add_subparsers(required=True)
    p = psub.add_parser("check"); p.add_argument("--snapshot", help="Optional pre-install snapshot to compare against"); p.set_defaults(func=h.cmd_protected_files_check)
    p = psub.add_parser("snapshot"); p.add_argument("--output", help="Optional snapshot path; defaults to .harness/protected-files.snapshot.json"); p.set_defaults(func=h.cmd_protected_files_snapshot)
    p = psub.add_parser("list"); p.set_defaults(func=h.cmd_protected_files_list)

    ep = sub.add_parser("executor", help="Inspect and validate executor adapters")
    esub = ep.add_subparsers(required=True)
    p = esub.add_parser("list"); p.set_defaults(func=h.cmd_executor_list)
    p = esub.add_parser("validate"); p.add_argument("executor", nargs="?"); p.set_defaults(func=h.cmd_executor_validate)
    ap = sub.add_parser("agents", help="Agent capability parity across vendor CLIs (SPEC-113): audit hooks/MCP/skills; pair renders vendor adapters from .harness/capabilities.json")
    asub = ap.add_subparsers(required=True)
    p = asub.add_parser("audit"); p.add_argument("--adopt", action="store_true", help="Seed .harness/capabilities.json from the current Claude wiring when absent, then audit"); p.set_defaults(func=h.cmd_agents, action="audit")
    p = asub.add_parser("pair"); p.add_argument("--apply", action="store_true", help="Execute the change plan (default: dry-run)"); p.set_defaults(func=h.cmd_agents, action="pair")
    p = asub.add_parser("claude-trust", help="SPEC-171 v2: pre-seed hasTrustDialogAccepted for this repo in ~/.claude.json so a fresh INTERACTIVE claude session skips the workspace trust dialog (spawned `claude -p` lanes never see it). Same canonical-render grant as codex-trust; denied = nothing written"); p.add_argument("--apply", action="store_true", help="Write it (default: dry-run report)"); p.set_defaults(func=h.cmd_agents, action="claude-trust")
    p = asub.add_parser("codex-trust", help="SPEC-171: report whether a harness-spawned codex lane gets --dangerously-bypass-hook-trust (grant ONLY when .codex/hooks.json is the committed canonical render of capabilities.json; fail-closed)"); p.add_argument("--flag", action="store_true", help="Print just the flag (empty line on deny) for hand-typed spawn recipes"); p.set_defaults(func=h.cmd_agents, action="codex-trust")
    p = asub.add_parser("skills", help="CAP.1 capability inventory: scoped skills (harness/user) with parity statuses + referencedBy; `show <id> [--file rel]` prints SKILL.md/scripts (path-confined)"); p.add_argument("action", nargs="?", choices=["list", "show"], default="list"); p.add_argument("id", nargs="?"); p.add_argument("--file", help="show: a script path relative to the skill dir (default SKILL.md)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=capabilities_view.cmd_agents_skills)
    p = asub.add_parser("mcp", help="CAP.1 MCP inventory across the five declaration points (capabilities.json, codex config, agent-sync manifest, target.json, services.json); env shown as key NAMES only; empty state teaches the grant paths"); p.add_argument("--json", action="store_true"); p.set_defaults(func=capabilities_view.cmd_agents_mcp)
    p = sub.add_parser("doctor", help="Repo-health WARN-only diagnostics (OneDrive/.git reparse/autocrlf)"); p.set_defaults(func=repo_health.cmd_doctor)
    p = sub.add_parser("spec-index", help="Read-only inventory of specs/ (scope, title, Scenario ids, legacy-frozen)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=spec_index.cmd_spec_index)
    p = sub.add_parser("research", help="Research-round admin + index: list rounds; `show <slug>` = parsed non-authoritative round view (phases/evidence/waves; --json w/o slug = full snapshot incl. live research WFs); guarded delete (dry-run by default; --apply, --allow-committed)"); p.add_argument("action", choices=["list", "show", "delete", "round"]); p.add_argument("slug", nargs="?"); p.add_argument("subaction", nargs="?"); p.add_argument("--json", action="store_true"); p.add_argument("--apply", action="store_true", help="Execute the delete (default: dry-run, deletes nothing)"); p.add_argument("--allow-committed", action="store_true", help="Permit deleting a git-tracked round"); p.add_argument("--executor", help="round advance: operator/test run-executor override (declared cohort executor remains the default)"); p.add_argument("--note", help="round approve: human delivery decision note (max 400 chars; state markers/fences refused)"); p.set_defaults(func=research_admin.cmd_research)
    p = sub.add_parser("failure-patterns", help="Repeat-failure rollup over the escalations + records ledgers (OB.1): deterministic clusters by failureClass/role/executor; read-only, verify-on-demand"); p.add_argument("--json", action="store_true"); p.set_defaults(func=failure_patterns.cmd_failure_patterns)
    p = sub.add_parser("docs-tree", help="Read-only scope-tagged inventory of docs/ + specs/ (indented tree or --json)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=docs_tree.cmd_docs_tree)
    p = sub.add_parser("config", help="Read-only MASKED inventory of expected env/config keys (SPEC-130): `config keys` presence table, `config list` the registry; raw values are never echoed"); p.add_argument("action", nargs="?", choices=["keys", "list"], default="keys"); p.add_argument("--json", action="store_true"); p.set_defaults(func=config_keys.cmd_config)
    p = sub.add_parser("anomaly-card", help="Deterministic anomaly feature card for a workflow cost-outlier (OB.3/SPEC-131): ledger-first factors (fan-out/dominant worker/duration) + evidence handles; read-only, rc 0"); p.add_argument("workflow_id"); p.add_argument("--json", action="store_true"); p.set_defaults(func=anomaly_card.cmd_anomaly_card)
    p = sub.add_parser("catalog", help="CE.4 demand-paged tool catalog: bare = one compact row per verb (names + short descs, TSV under HARNESS_AGENT_OUTPUT=compact); `catalog <verb> [subverb]` pages in that ONE verb's full --help; --json adds the disclosure-overhead measurement"); p.add_argument("verb", nargs="*"); p.add_argument("--json", action="store_true"); p.set_defaults(func=cli_catalog.cmd_catalog)
    p = sub.add_parser("graph", help="Graph providers + metrics: `providers` lists (builtin + config-declared externals; * = active); `set <name>` selects (validated); `metrics [--target N]` = structure/freshness(shared gate rule)/artifacts/consumption snapshot. Broken externals fall back to the builtin, loudly"); p.add_argument("action", nargs="?", choices=["providers", "set", "metrics"], default="providers"); p.add_argument("name", nargs="?"); p.add_argument("--target", help="metrics: a registered target's graph instead of the harness's"); p.add_argument("--json", action="store_true"); p.set_defaults(func=graph_providers.cmd_graph)
    p = sub.add_parser("keys", help="OS-vault key management (decision #2, keyring 25.6.0 REQUIRED): `list` presence+backend+lastRotated (masked); `set NAME` reads the value from STDIN never argv; `unset NAME`. Read cascade: environ -> keyring -> missing (the .env tier was removed, keys-keyring v2)"); p.add_argument("action", nargs="?", choices=["list", "set", "unset"], default="list"); p.add_argument("name", nargs="?"); p.add_argument("--json", action="store_true"); p.set_defaults(func=keys_vault.cmd_keys)
    p = sub.add_parser("services", help="Declared long-lived dependencies (svc-registry P0): list | start <name> (idempotent, ready-probed, hidden console) | stop <name> (orphan-free taskkill /T) | status (reaps dead/ownerless). Registry: .harness/services.json or target.json services"); p.add_argument("action", nargs="?", choices=["list", "start", "stop", "status"], default="list"); p.add_argument("name", nargs="?"); p.add_argument("--target", help="Operate on a registered target's declared services"); p.add_argument("--json", action="store_true"); p.set_defaults(func=services.cmd_services)
    p = sub.add_parser("tasks", help="Tasks board + canonical store (decision #3): `list` derived Kanban (compact TSV under HARNESS_AGENT_OUTPUT=compact, TE.5); `import` freezes the backlog tables into .harness/state/tasks.json; add/move/close/delete/note write the store (single write path); `refine` = bounded read-only model run proposing a plan (writes .harness/runs/task-refine-*.plan.md, store untouched); `plan --from-run` appends an approved proposal; `dispatch` ships card+plan through route --task --dispatch (WITHHELD/REFUSED relayed)"); p.add_argument("action", nargs="?", choices=["list", "show", "import", "add", "set", "move", "close", "delete", "note", "dep", "plan", "refine", "dispatch"], default="list"); p.add_argument("params", nargs="*", help="show: <id> (one row with its full prose) | add: <title…> | set: <id> (re-grade --priority/--size/--category) | move: <id> <lane> | dep: <id> <kind> <otherId> (kind=depends-on|blocks|relates-to|duplicates, or the literal no-deps) | close/delete/note/plan/refine/dispatch: <id>"); p.add_argument("--category", help="list: filter by category; add/set: category for the task"); p.add_argument("--lane", help="list: filter rows by lane (backlog|running|review|done)"); p.add_argument("--id", help="add: explicit task id (default: slug of the title)"); p.add_argument("--size", help="add/set: S|M|L|XL"); p.add_argument("--priority", help="add/set: P1|high|… (set: empty string clears)"); p.add_argument("--text", help="note: the owner's complementary notes (`-` reads them from stdin)"); p.add_argument("--body", help="add: the task's full prose. `-` reads it from STDIN — multi-KB rows do not belong in argv (the `keys set` precedent); over BODY_CAP is REFUSED, never truncated"); p.add_argument("--from-run", help="plan: proposal file name under .harness/runs (task-refine-*.plan.md)"); p.add_argument("--model", help="refine: model card override for the read-only planner"); p.add_argument("--effort", help="refine: effort override"); p.add_argument("--executor", help="refine/dispatch: executor (default claude; the generic stub never plans)"); p.add_argument("--topo", action="store_true", help="list: print the Kahn topological execution order derived from inline dep tags (blocks:/depends-on:), hard-detecting mutual-dependency cycles"); p.add_argument("--sort", choices=["priority"], help="list: sort rows by priority rank (P1 > high > P2 > med > P3 > low > other > none); stable within a rank"); p.add_argument("--migrate", action="store_true", help="import: ONE-TIME reconciliation (backlog-json-canonical) — refuses on a duplicate id, propagates struck document rows onto store rows still open, and retires rows the document dropped (archived -> done+archivedAt, parse artifacts purged, open document-sourced strays reported)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=tasks_board.cmd_tasks)
    p = sub.add_parser("provenance", help="Derived provenance+dependency graph slice (backlog-groom P2): `provenance <TOKEN>` = what cites this token / what it cites, bounded (never the whole graph). Every edge is a CLAIM (status/confidence/provenanceTag, no `fact`): explicit dep tags VERIFIED, DECISIONS/git+item co-occurrence PROPOSED. Compact TSV under HARNESS_AGENT_OUTPUT=compact. --verified restricts to the VERIFIED downstream default"); p.add_argument("token", nargs="?", help="a reference token (SPEC-116, EXP-25, D033, T-…) or backlog id"); p.add_argument("--verified", action="store_true", help="only VERIFIED edges (explicit dependency tags)"); p.add_argument("--ripple", action="store_true", help="backlog-groom P3a: instead of the slice, print the bounded-hop impact set — who is AFFECTED (id/hops/minConfidence) if this token changes, over VERIFIED order-edges (measure-only, changes no status)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=dep_graph.cmd_provenance)
    p = sub.add_parser("checkpoint", help="In-flight work checkpoint (ckpt): bare = show the block; `checkpoint \"note\" [--item X] [--phase spec|test|impl|verify|commit] [--verify CMD]` rewrites it in .harness/context/NEXT_STEPS.md (omitted fields carry over, notes redacted); --clear ends it; --render prints the post-compact reinjection payload the SessionStart hook emits"); p.add_argument("note", nargs="*"); p.add_argument("--item"); p.add_argument("--phase"); p.add_argument("--verify", metavar="CMD"); p.add_argument("--clear", action="store_true"); p.add_argument("--render", action="store_true"); p.set_defaults(func=context_checkpoint.cmd_checkpoint)
    p = sub.add_parser("intake", help="Durable requirement-intake queue (cm-6): the triage hook captures feature-shaped prompts; `list` = pending asks (`--decided` = the decided ones, newest first), `add <text…>` manual capture, `decide <id> spec|backlog|discard|experiment [--note]` records the triage; doctor warns on pending >7d and on decided-but-noteless"); p.add_argument("action", nargs="?", choices=["list", "add", "decide"], default="list"); p.add_argument("params", nargs="*", help="add: <ask…> | decide: <id> <decision>"); p.add_argument("--note", help="decide: rationale recorded on the entry"); p.add_argument("--decided", action="store_true", help="list: show DECIDED entries (status+decidedAt+note), newest first, instead of pending"); p.add_argument("--json", action="store_true"); p.set_defaults(func=intake_queue.cmd_intake)
    p = sub.add_parser("decide", help="Pending human decisions as plain questions with selectable answers (SPEC-145): bare = interactive picker; --list [--json] = read-only; `decide <id> <choice>` = one-shot. Covers intake triage + escalation resolve; no-input lists, never mutates"); p.add_argument("params", nargs="*", help="one-shot form: <id> <choice>; empty = interactive (or --list)"); p.add_argument("--list", action="store_true", help="list pending decisions, mutate nothing"); p.add_argument("--note", help="note recorded on the decision (defaults to the deciding surface)"); p.add_argument("--expected-digest", help="C12: bind the approval to the digest shown in --list; refuse if the decision content changed since (TOCTOU guard)"); p.add_argument("--allow-expired", action="store_true", help="apply an approval past decisionInbox.expiryHours after re-reading it (digest check still applies)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=decision_inbox.cmd_decide)
    p = sub.add_parser("review", help="Overseer review toolkit (ort): deterministic worker-diff checks vs HEAD — footprint vs the plan brief (--plan), blank-deletion fraud signature, HEAD-attributed mojibake delta, removed-assertion gaming. Advisory: always rc 0, the overseer judges the WARN rows"); p.add_argument("--plan", help="Plan brief whose `## File footprint` bounds the worker"); p.add_argument("--json", action="store_true"); p.set_defaults(func=overseer_review.cmd_review)
    p = sub.add_parser("oracle", help="Independent-oracle probes (CQ.5 slice, observe-only): `mutate` plants <=3 deterministic AST mutants in diff-changed functions and demands the diff's own scenario FAIL (killed/survived/error/timeout/skipped); tree restored byte-identical. `canary` (W29) records ONE probe point in the ledger (live diff, or the synthetic machinery check when the diff has nothing to probe) so gate recall becomes a series; `canary --trend` prints the series. `waive --reason \"…\"` records the overseer's judged tolerance for the survivors on the CURRENT staged surface, turning the third commit-leg's block into a warn that carries the reason (empty reason REFUSED)"); p.add_argument("action", nargs="?", choices=["mutate", "canary", "waive"], default="mutate"); p.add_argument("--diff", default="HEAD", help="Diff base (default HEAD; the working tree is the mutated side)"); p.add_argument("--scenario", help="Override the diff-linked scenario"); p.add_argument("--max-mutants", type=int, default=3); p.add_argument("--timeout", type=int, default=120); p.add_argument("--record", action="store_true", help="mutate: also persist the report as a canary point (tags oracle+canary)"); p.add_argument("--trend", action="store_true", help="canary: print the recorded series instead of running a probe"); p.add_argument("--reason", help="waive: the judged tolerance for the surviving mutants (required, non-empty)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=mutation_probe.cmd_oracle)
    p = sub.add_parser("validate", help="Pre-commit validation gate (SPEC-137): validate the staged index snapshot and stamp it; --check prints the hook decision only"); p.add_argument("--staged", action="store_true", help="Validate the staged surface snapshot (the only mode today)"); p.add_argument("--check", action="store_true", help="Decision only: print the pre-commit verdict and exit 0/1 (what the hook calls)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=validation_stamp.cmd_validate)
    p = sub.add_parser("gate-staged", help="Launch `validate --staged` DETACHED (SPEC-137): tees to .harness/runs/gate-staged-<ts>.log, writes a completion marker (exit code), returns the log path + PID immediately (foreground can no longer be hard-killed mid-gate)"); p.add_argument("--run", action="store_true", help=argparse.SUPPRESS); p.add_argument("--marker", help=argparse.SUPPRESS); p.add_argument("--json", action="store_true"); p.add_argument("--wait", action="store_true", help="Observe the marker until the gate settles (poll 5s, cap 45min) and exit with the gate's exit code; pure observer -- killing the waiter never kills the detached gate. Agent shells run this under run_in_background so the completion notification wakes them (deny_hitl_flags enforces it)"); p.set_defaults(func=gate_staged.cmd_gate_staged)
    p = sub.add_parser("gate-divergence", help="End-of-loop serial<->parallel divergence probe (owner 2026-07-21): diff the per-scenario rc maps of the latest serial vs latest parallel scenarios runs in the gate-perf sidecar; every divergence is a flake-candidate that gets a backlog row, never a shrug"); p.set_defaults(func=gate_perf.cmd_gate_divergence)
    p = sub.add_parser("hold-recover", help="Restore .harness state parked by a crashed gate's abandoned hold (row gate-hold-abandoned-detector): runs the same recovery the next gate would, as a DELIBERATE verb -- refuses a hold whose recorded pid is still alive (that is a running gate)"); p.set_defaults(func=h.cmd_hold_recover)
    p = sub.add_parser("experiment", help="Experiment-lifecycle registry (SPEC-116 pack): pre-registered hypotheses -> active (reviewBy nag) -> shipped|shelved with evidence; probes measure-only, control lands via SPEC-116 citing the EXP-id"); p.add_argument("action", nargs="?", choices=["list", "add", "show", "activate", "record", "extend", "verdict", "refine", "plan", "dispatch"], default="list"); p.add_argument("params", nargs="*", help="add: <EXP-N> <title…> | show/activate/record/extend/refine/plan/dispatch: <EXP-N> [value…] | verdict: <EXP-N> shipped|shelved"); p.add_argument("--model", help="refine: model-card override"); p.add_argument("--effort", help="refine: reasoning-effort override"); p.add_argument("--executor", help="refine/dispatch: claude|codex (default claude)"); p.add_argument("--from-run", help="plan: accepted experiment-refine-*.plan.md under .harness/runs/"); p.add_argument("--hypothesis"); p.add_argument("--metric"); p.add_argument("--baseline"); p.add_argument("--success", help="successCriteria field"); p.add_argument("--abandon", help="abandonCriteria field"); p.add_argument("--reversal", help="reversalPlan field"); p.add_argument("--source"); p.add_argument("--review-by", help="activate/extend: explicit ISO reviewBy (default now+14d)"); p.add_argument("--status", help="list: filter by proposed|active|shipped|shelved"); p.add_argument("--evidence"); p.add_argument("--reopen-trigger"); p.add_argument("--note"); p.add_argument("--grade", type=int, choices=[1, 2, 3, 4], help="add/verdict: evidence grade 1-4 (App H) — optional"); p.add_argument("--measure", help="record: structured metric NAME (the ratified additive measurements metrics[] schema)"); p.add_argument("--value", type=float, help="record: structured metric value (a number; required with --measure)"); p.add_argument("--unit", help="record: structured metric unit (e.g. fraction, ms, count)"); p.add_argument("--n", type=int, help="record: structured sample size n"); p.add_argument("--ci-lo", type=float, help="record: structured CI lower bound"); p.add_argument("--ci-hi", type=float, help="record: structured CI upper bound"); p.add_argument("--ci-method", help="record: CI method (e.g. anytime-valid, bootstrap)"); p.add_argument("--noise-floor", type=float, help="record: structured noise floor threshold"); p.add_argument("--artifact", help="record: pointer to the raw result artifact"); p.add_argument("--variant", choices=["baseline", "candidate"], help="record: tag for the baseline-vs-candidate delta view"); p.add_argument("--json", action="store_true"); p.set_defaults(func=experiment_registry.cmd_experiment)
    p = sub.add_parser("route", help="SPEC-144 (opt-in): classify ONE demand -> route decision (dynamic-workflow|pre-defined-profile|inline) + compact dispatch brief + the specialized-overseer spawn command. Phase 2 plumbing: --triage-prompt prints the Sonnet router prompt; --verdict <json> normalizes the overseer's typed return. No loop, no live model call, no writes yet (Phase 3)"); p.add_argument("words", nargs="*"); p.add_argument("--task", help="the demand string (alternative to positional words)"); p.add_argument("--executor", help="executor for the produced dispatch spawn command"); p.add_argument("--triage-prompt", action="store_true", help="print the Sonnet 5 high router triage prompt for the demand instead of running the placeholder"); p.add_argument("--verdict", help="normalize the specialized overseer's typed return JSON (consume_verdict) and exit"); p.add_argument("--loop", action="store_true", help="Phase 3 (opt-in): drain the intake feed as the conductor-B driver -- live triage + plan/implement/apply-merge/commit choreography, bounded"); p.add_argument("--heartbeat", action="store_true", help="Phase 3 re-entry check: print {shouldResume,...} (never spawns) so the session agent decides whether to re-invoke --loop once"); p.add_argument("--max-demands", type=int, default=5, help="--loop: max demands drained this run (bound)"); p.add_argument("--max-failures", type=int, default=2, help="--loop: stop after N consecutive dispatch failures"); p.add_argument("--approve-writes", metavar="TOKEN", help="--loop: the controlled-writes approval token (owner-typed; the driver has NO default) -- omit for a read-only run"); p.add_argument("--dry-run", action="store_true", help="--loop: read-only -- no live model, no writes, no commit, no queue mutation"); p.add_argument("--only", metavar="ENTRY_ID", help="--loop: restrict the pull to ONE intake entry id (controlled runs; composes with --max-demands)"); p.add_argument("--dispatch", action="store_true", help="execute the produced spawn DETACHED (log under .harness/runs/); single-demand only, ignored under --loop"); p.set_defaults(func=h.cmd_route)
    p = sub.add_parser("reckon", help="Record a review reckon verdict against the CURRENT staged fingerprint (SPEC-157): `reckon --record --verdict no-blocker|blocker [--note …]`. The commit-gate enforces gate=pass AND reckon=no-blocker for risk-bearing changes"); p.add_argument("--record", action="store_true", help="Stamp the verdict (the only mode today)"); p.add_argument("--verdict", choices=["no-blocker", "blocker"], help="no-blocker = SHIP (or FIX already resolved); blocker = a shipping blocker remains"); p.add_argument("--note", help="Free-text note carried on the reckon record"); p.add_argument("--json", action="store_true"); p.set_defaults(func=validation_stamp.cmd_reckon)
    p = sub.add_parser("verify-status", help="Parallel-verify join view (SPEC-157): the gate (validation) + reckon decisions over the CURRENT staged surface, the staged fingerprint, and readyToCommit"); p.add_argument("--json", action="store_true"); p.set_defaults(func=validation_stamp.cmd_verify_status)
    p = sub.add_parser("audit", help="Mechanized pre-merge audit — the FOURTH commit-join leg (gate || reckon || mutate || audit). `run` assembles the adversarial packet from the STAGED surface and launches N governed seats detached (N from the band ladder in .harness/audit-policy.json; --seats/--executor override, --dry-run resolves the seat argvs without spawning); `collect` parses each seat VERDICT, applies the quorum (unanimity to SHIP, any BLOCK blocks, dissent recorded) and stamps it against the staged fingerprint; `record --verdict ship|block` is the overseer ARBITER path; `waive --reason \"…\"` demotes the block to a warn carrying the judged tolerance; `check` prints the commit-gate decision (exit 0/1)"); p.add_argument("action", nargs="?", choices=["run", "collect", "record", "check", "waive"], default="check"); p.add_argument("--plan", help="run: plan brief whose intent the seats audit the diff against"); p.add_argument("--seats", type=int, help="run: override the band ladder's N (below the planned N is RECORDED, never silent)"); p.add_argument("--executor", help="run: pin every seat to one executor (recorded as a vendorFallback at N>=2)"); p.add_argument("--dry-run", action="store_true", help="run: build the packet and resolve every seat argv through the governed spawn seam, launching nothing"); p.add_argument("--lane-seat", help="run: the seat that PRODUCED the staged change (role:model:effort) — the attribution for the audit-caught defect capsules a BLOCK mints"); p.add_argument("--verdict", choices=["ship", "block"], help="record: the arbiter's verdict"); p.add_argument("--note", help="record/collect: free-text note carried on the audit record"); p.add_argument("--reason", help="waive: the judged tolerance (required, non-empty)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=audit_leg.cmd_audit)
    p = sub.add_parser("fuel", help="Vendor fuel gauge (N-VENDORCREDIT v1): `probe` refreshes EVERY configured vendor in one sequential pass (pinned surfaces: claude /usage, codex login+rollout, kimi /usages, http /models) and writes canonical .harness/state/vendor-fuel.json ATOMICALLY — all-or-nothing on purpose (owner 2026-07-28): a per-vendor probe both clobbered unlisted rows and let readings age apart, skewing the R13 gas balancer. `show` reads with age WITHOUT probing. pct is real where the vendor exposes one, null otherwise (never fabricated); --json emits the full machine-readable state (the R13 load-balance input)"); p.add_argument("action", nargs="?", choices=["probe", "show"], default="show"); p.add_argument("--json", action="store_true"); p.add_argument("--mint", action="store_true", help="after the pass, refresh stale codex/kimi gauges by running ONE bare trivial turn each (cheapest model, lowest effort, empty cwd so no project capsule loads — owner 2026-07-30), then re-probe once; spends a sliver of that vendor's own quota, so it is opt-in and NEVER the default"); p.set_defaults(func=vendor_fuel.cmd_fuel)
    p = sub.add_parser("gate-perf", help="wf-gate-observability: read-only aggregate of the gate-perf sidecar — per-scenario count/p50/max subprocessS, share-of-gate %%, ranked slowest-first, plus the snapshot/restore isolation tax. `--last N` (default 10) runs; `--json` for all scenarios. Measures the drum, changes nothing"); p.add_argument("--last", type=int, default=10, help="Aggregate over the last N gate runs (default 10)"); p.add_argument("--json", action="store_true"); p.set_defaults(func=gate_perf.cmd_gate_perf)
    p = sub.add_parser("artifacts", help="Worker-result pipeline: list derived worker artifacts (handoff + runs roots, on-read classification, newest first). --type narrows to image|log|report|audit|ledger|evidence. Read-only; serving goes through /api/artifacts with its own confinement"); p.add_argument("--type", choices=artifacts.ARTIFACT_TYPES, help="Narrow to one artifact type"); p.set_defaults(func=artifacts.cmd_artifacts)
    p = sub.add_parser("playbook", help="Role -> playbook resolution over .harness/routing/playbook-registry.json (SPEC-170): `playbook <role>` [--list] prints the ordered de-duped extends-chain playbooks; --compose prints the compiled Effective Playbook (SPEC-173: precedence + dedup, the full-contract read); --verify grades registry health (dangling/orphan/broken-ref/pin-duplication/lock-drift, red -> rc 1) and regenerates the chain lockfile"); p.add_argument("role", nargs="?"); p.add_argument("--list", action="store_true"); p.add_argument("--compose", action="store_true"); p.add_argument("--verify", action="store_true"); p.add_argument("--json", action="store_true"); p.set_defaults(func=playbook_registry.cmd_playbook)
